    public void setWidth(double w) { width = w; }
    public double getWidth() { return width; }
    public double findArea() { return width * height; }
}
public class Main {
    static void addOne(int n) { n++; }
    static void grow(Rectangle r) { r.setWidth(r.getWidth() + 1); }
    public static void main(String[] args) {
        int x = 5;
        Rectangle rect = new Rectangle(1.0, 1.0);
        addOne(x);
        grow(rect);
        System.out.println(x + " " + rect.getWidth());
    }
}

class Rectangle {
    private double width, height;
    public Rectangle(double w, double h) { width = w; height = h; }
    public void setWidth(double w) { width = w; }
    public double getWidth() { return width; }
    public double findArea() { return width * height; }
}
public class Main {
    static void swap(Rectangle a, Rectangle b) {
        Rectangle t = a; a = b; b = t;
    }
    public static void main(String[] args) {
        Rectangle r1 = new Rectangle(1.0, 1.0);
        Rectangle r2 = new Rectangle(9.0, 9.0);
        swap(r1, r2);
        System.out.println(r1.getWidth() + " " + r2.getWidth());
    }
}

